function mergeBaseIntoBranchOrThrow(): string {
  const branch = resolveBranch();
  if (unfinishedMerge()) {
    mcpFail(
      "A merge is already in progress on this branch. Resolve its conflicts and call commit_and_push to " +
      "close it before merging another base in.",
