  const commit = head.stdout.trim();
  pushBranch(branch);
  logOp("merge_base_into_branch", { branch, base, status: "merged", base_sha: baseSha, commit });
  return JSON.stringify({ status: "merged", branch, base, base_sha: baseSha, commit });
